from collections import deque

blocks = ('block1', 'block2')
start = ('block2', frozenset(('block1',)), frozenset())
goal = (None, frozenset(('block1', 'block2')), frozenset())

def clear(state, b):
    _, _, on = state
    return all(bottom != b for top, bottom in on)

def successors(state):
    holding, ontable, on = state
    if holding is not None:
        yield (None, ontable | frozenset((holding,)), on), f"(putdown {holding})"
        for c in blocks:
            if c != holding and clear(state, c):
                yield (None, ontable, on | frozenset(((holding, c),))), f"(stack {holding} {c})"
    else:
        for b in blocks:
            if b in ontable and clear(state, b):
                yield (b, ontable - frozenset((b,)), on), f"(pickup {b})"
        for b, c in on:
            if clear(state, b):
                yield (b, ontable, on - frozenset(((b, c),))), f"(unstack {b} {c})"

