from collections import deque

def canonical(stacks, held):
    stacks = tuple(sorted(tuple(s) for s in stacks if s))
    return (stacks, held)

def moves(state):
    stacks, held = state
    result = []
    if held is None:
        for i, stack in enumerate(stacks):
            top = stack[-1]
            if len(stack) == 1:
                new_stacks = list(stacks)
                del new_stacks[i]
                ns = canonical(new_stacks, top)
                result.append((f"(pickup block{top})", ns))
            else:
                below = stack[-2]
                new_stacks = list(stacks)
                new_stacks[i] = stack[:-1]
                ns = canonical(new_stacks, top)
                result.append((f"(unstack block{top} block{below})", ns))
    else:
        new_stacks = list(stacks) + [(held,)]
        ns = canonical(new_stacks, None)
        result.append((f"(putdown block{held})", ns))
        for i, stack in enumerate(stacks):
            top = stack[-1]
            new_stacks = list(stacks)
            new_stacks[i] = stack + (held,)
            ns = canonical(new_stacks, None)
            result.append((f"(stack block{held} block{top})", ns))
    return result

def num_stacks(state):
    stacks, held = state
    return len(stacks)

