n = 10

loc0 = [0] * (n + 1)
loc0[1] = 10
loc0[2] = 1
loc0[9] = 6

initial = (tuple(loc0), 0, 0)

def is_clear(loc, x):
    for b in range(1, n + 1):
        if loc[b] == x:
            return False
    return True

def is_goal(state):
    loc, held, frozen = state
    if held != 0:
        return False
    if loc[1] != 8:
        return False
    for b in range(2, n + 1):
        if loc[b] != 0:
            return False
    return True

def get_actions(state):
    loc, held, frozen = state
    actions = []

    if held == 0:
        for x in range(1, n + 1):
            y = loc[x]
            if y > 0 and is_clear(loc, x):
                actions.append(("unstack", x, y))

        for x in range(1, n + 1):
            if loc[x] == 0 and is_clear(loc, x) and not ((frozen >> x) & 1):
                actions.append(("pickup", x, None))
    else:
        x = held
        for y in range(1, n + 1):
            if y != x and is_clear(loc, y):
                actions.append(("stack", x, y))
        actions.append(("putdown", x, None))

    return actions

def apply_action(state, action):
    loc, held, frozen = state
    loc = list(loc)
    name, x, y = action

    if name == "pickup":
        loc[x] = -1
        held = x
    elif name == "unstack":
        loc[x] = -1
        held = x
    elif name == "putdown":
        loc[x] = 0
        held = 0
        frozen |= (1 << x)
    elif name == "stack":
        loc[x] = y
        held = 0

    return (tuple(loc), held, frozen)

