from collections import deque

initial = (0, 0, 0, 6, 1, 2, 5, 7)
goal = (0, 0, 0, 0, 0, 5, 0, 0)


def neighbors(state):
    loc = list(state)
    held = None
    for i, v in enumerate(loc):
        if v == -1:
            held = i + 1
            break

    res = []

    if held is None:
        for b in range(1, 9):
            if loc[b - 1] == 0 and all(v != b for v in loc):
                new = loc.copy()
                new[b - 1] = -1
                res.append((tuple(new), f"(pickup block{b})"))

        for b in range(1, 9):
            if loc[b - 1] > 0 and all(v != b for v in loc):
                y = loc[b - 1]
                new = loc.copy()
                new[b - 1] = -1
                res.append((tuple(new), f"(unstack block{b} block{y})"))
    else:
        x = held
        new = loc.copy()
        new[x - 1] = 0
        res.append((tuple(new), f"(putdown block{x})"))

        for y in range(1, 9):
            if y == x:
                continue
            if loc[y - 1] == -1:
                continue
            if all(v != y for v in loc):
                new = loc.copy()
                new[x - 1] = y
                res.append((tuple(new), f"(stack block{x} block{y})"))

    return res


def reverse_neighbors(state):
    loc = list(state)
    held = None
    for i, v in enumerate(loc):
        if v == -1:
            held = i + 1
            break

    res = []

    if held is not None:
        x = held

        if all(v != x for v in loc):
            new = loc.copy()
            new[x - 1] = 0
            res.append((tuple(new), f"(pickup block{x})"))

        for y in range(1, 9):
            if y == x:
                continue
            if loc[y - 1] == -1:
                continue
            if all(v != y for v in loc):
                new = loc.copy()
                new[x - 1] = y
                res.append((tuple(new), f"(unstack block{x} block{y})"))
    else:
        for x in range(1, 9):
            if loc[x - 1] == 0 and all(v != x for v in loc):
                new = loc.copy()
                new[x - 1] = -1
                res.append((tuple(new), f"(putdown block{x})"))

        for x in range(1, 9):
            y = loc[x - 1]
            if y > 0 and all(v != x for v in loc):
                new = loc.copy()
                new[x - 1] = -1
                res.append((tuple(new), f"(stack block{x} block{y})"))

    return res


