        9: 6,
        2: 0,
        3: 2,
        7: 3,
        4: 7,
        11: 4,
        12: 11,
        8: 12,
        1: 8,
        10: 1,
        5: 10,
    }

    def allowed(x, y):
        if y == 0:
            return True
        return not (x % 2 == 1 and y % 2 == 0)

    for x, y in goal_support.items():
        if not allowed(x, y):
            print("No plan")
            return

    def clear(x, on):
        return all(on[i] != x for i in range(1, n + 1))

    start_on = (0,) + (0,) * n
