    for x, y in goal_support.items():
        goal_on_list[x] = y
    goal = (0, tuple(goal_on_list))

    queue = deque([initial])
    parent = {initial: (None, None)}

    while queue:
        state = queue.popleft()

        if state == goal:
            actions = []
            cur = state
            while parent[cur][0] is not None:
                prev, action = parent[cur]
                actions.append(action)
                cur = prev
            actions.reverse()
            print("\n".join(actions))
            return

        holding, on = state

        if holding == 0:
            for x in blocks:
                if on[x] == 0 and clear(x, on):
                    new_on = list(on)
                    new_on[x] = -1
                    new_state = (x, tuple(new_on))
                    if new_state not in parent:
                        parent[new_state] = (state, f"(pickup block{x})")
                        queue.append(new_state)

