import heapq

def heuristic(state):
    loc = state[:9]
    holding = state[9]
    goal_support = [0, 0, 4, 2, 1, 0, 3, 0, 8]
    must = [False] * 10

    for b in range(1, 10):
        if b == holding:
            must[b] = True
        else:
            if loc[b - 1] != goal_support[b - 1]:
                must[b] = True

    changed = True
    while changed:
        changed = False
        for y in range(1, 10):
            if not must[y]:
                lower = loc[y - 1]
                if lower > 0 and must[lower]:
                    must[y] = True
                    changed = True

    m = sum(must[1:])
    return 2 * m - (1 if holding != 0 else 0)


def successors(state):
    loc = list(state[:9])
    holding = state[9]
    out = []

    if holding == 0:
        for x in range(1, 10):
            if loc[x - 1] < 0:
                continue

            clear = True
            for y in range(1, 10):
                if loc[y - 1] == x:
                    clear = False
                    break
            if not clear:
                continue

            under = loc[x - 1]
            nl = loc.copy()
            nl[x - 1] = -1
            ns = tuple(nl) + (x,)

            if under == 0:
                out.append((ns, f"(pickup block{x})"))
            else:
                out.append((ns, f"(unstack block{x} block{under})"))

    else:
        x = holding

        nl = loc.copy()
        nl[x - 1] = 0
        ns = tuple(nl) + (0,)
        out.append((ns, f"(putdown block{x})"))

        for y in range(1, 10):
            if y == x:
