            if loc[y - 1] < 0:
                continue

            clear = True
            for z in range(1, 10):
                if loc[z - 1] == y:
                    clear = False
                    break
            if not clear:
                continue

            nl = loc.copy()
            nl[x - 1] = y
            ns = tuple(nl) + (0,)
            out.append((ns, f"(stack block{x} block{y})"))

    return out


def reconstruct(parent, goal):
    actions = []
    state = goal
    while state in parent:
        prev, act = parent[state]
        actions.append(act)
        state = prev
    actions.reverse()
    return actions


def solve():
    init_dict = {1: 9, 2: 7, 3: 5, 4: 1, 5: 6, 6: 4, 7: 0, 8: 3, 9: 2}
    init = tuple(init_dict[i] for i in range(1, 10)) + (0,)
    goal = (0, 0, 4, 2, 1, 0, 3, 0, 8, 0)

    if init == goal:
        return []

    gscore = {init: 0}
    parent = {}
    h0 = heuristic(init)
    pq = [(h0, h0, 0, init)]
    counter = 1
    max_cost = 24
    limit = 50000
    expansions = 0

    while pq:
        f, h, _, state = heapq.heappop(pq)
        gcur = gscore.get(state)

        if gcur is None or f != gcur + h:
            continue

        if state == goal:
            return reconstruct(parent, goal)

        expansions += 1
        if expansions > limit:
            return None

        for nxt, act in successors(state):
            ng = gcur + 1
            if ng > max_cost:
                continue

            nh = heuristic(nxt)
            if ng + nh > max_cost:
                continue

            if ng < gscore.get(nxt, 10**9):
                gscore[nxt] = ng
                parent[nxt] = (state, act)
                heapq.heappush(pq, (ng + nh, nh, counter, nxt))
                counter += 1

    return None


