import heapq
from functools import lru_cache


def main():
    n = 12
    final_held = 1

    start = [0] * (n + 1)
    start[9] = 10
    start[2] = 9
    start[1] = 2
    start[11] = 1
    start[12] = 11
    start[5] = 12
    start[6] = 5
    start[3] = 7

    goal = [0] * (n + 1)
    goal[1] = -1
    goal[7] = 10
    goal[8] = 9
    goal[9] = 2
    goal[10] = 11
    goal[11] = 3
    goal[12] = 5

    def is_goal(s):
        if s[0] != final_held:
            return False
        if s[final_held] != -1:
            return False
        for b in range(2, n + 1):
            if s[b] != goal[b]:
                return False
        return True

    @lru_cache(maxsize=None)
    def heuristic(s):
        held = s[0]
        stable_memo = [-1] * (n + 1)

        def stable(b):
            if b == 0:
                return True
            if stable_memo[b] != -1:
                return stable_memo[b] == 1

            if b == final_held:
                result = (held == b)
            else:
                sb = s[b]
                if sb == -1:
                    result = False
                elif sb != goal[b]:
                    result = False
                elif sb == 0:
                    result = True
                else:
                    result = stable(sb)

            stable_memo[b] = 1 if result else 0
            return result

        for b in range(1, n + 1):
            stable(b)

        total_other = 0

        for b in range(1, n + 1):
            if b == final_held:
                continue

            sb = s[b]

            if sb == -1:
                cost = 1
            elif sb != goal[b]:
                cost = 2
            else:
                if sb == 0:
                    cost = 0
                elif not stable(sb):
                    cost = 4
                else:
                    cost = 0

            total_other += cost

        b = final_held

        if held == b:
            cost_b = 2 if total_other > 0 else 0
        else:
            cost_b = 1
            p = s[b]

            need_temporary = False

            if p > 0 and not stable(p):
                need_temporary = True

            if p > 0:
                for x in range(1, n + 1):
                    if x != b and goal[x] == p:
                        need_temporary = True
                        break

            if need_temporary:
                cost_b = 3

        return total_other + cost_b

    def successors(s):
        held = s[0]

        has_on = [False] * (n + 1)
        for c in range(1, n + 1):
            support = s[c]
            if support > 0:
                has_on[support] = True

        if held == 0:
            for b in range(1, n + 1):
                if s[b] == -1 or has_on[b]:
                    continue

                support = s[b]
                ns = list(s)
                ns[0] = b
                ns[b] = -1

                if support == 0:
                    yield ("pickup", b), tuple(ns)
                else:
                    yield ("unstack", b, support), tuple(ns)
        else:
            x = held

            ns = list(s)
            ns[0] = 0
            ns[x] = 0
            yield ("putdown", x), tuple(ns)

            for y in range(1, n + 1):
                if y == x:
                    continue
                if s[y] == -1 or has_on[y]:
                    continue

                ns = list(s)
                ns[0] = 0
                ns[x] = y
                yield ("stack", x, y), tuple(ns)

    start_state = tuple(start)

    best_g = {start_state: 0}
    parent = {start_state: (None, None)}

    counter = 0
    pq = [(heuristic(start_state), 0, counter, start_state)]

    while pq:
        f, g, _, state = heapq.heappop(pq)

        if g != best_g.get(state):
            continue

        if is_goal(state):
            actions = []
            cur = state

            while True:
                prev, action = parent[cur]
                if prev is None:
                    break
                actions.append(action)
                cur = prev

            actions.reverse()

            for action in actions:
                if action[0] == "pickup":
                    print(f"(pickup block{action[1]})")
                elif action[0] == "putdown":
                    print(f"(putdown block{action[1]})")
                elif action[0] == "unstack":
                    print(f"(unstack block{action[1]} block{action[2]})")
                elif action[0] == "stack":
                    print(f"(stack block{action[1]} block{action[2]})")

            return

        for action, next_state in successors(state):
            next_g = g + 1

            if next_g < best_g.get(next_state, 10**9):
                best_g[next_state] = next_g
                parent[next_state] = (state, action)

                counter += 1
                heapq.heappush(
                    pq,
                    (next_g + heuristic(next_state), -next_g, counter, next_state),
                )

    print("No plan")


