def make_state(held, stacks):
    below = [0] * 9
    above = [0] * 9
    for stack in stacks:
        prev = 0
        for x in stack:
            below[x] = prev
            if prev:
                above[prev] = x
            prev = x
        if prev:
            above[prev] = 0
    return (held, tuple(below), tuple(above))


def successors(state):
    held, below_t, above_t = state
    below = below_t
    above = above_t
    result = []

    if held == 0:
        for x in range(1, 9):
            if above[x] == 0:
                y = below[x]
                if y == 0:
                    result.append(((x, below_t, above_t), ('pickup', x)))
                else:
                    nb = list(below_t)
                    na = list(above_t)
                    nb[x] = 0
                    na[x] = 0
                    na[y] = 0
                    result.append(((x, tuple(nb), tuple(na)), ('unstack', x, y)))
    else:
        x = held
        result.append(((0, below_t, above_t), ('putdown', x)))
        for y in range(1, 9):
            if y != x and above[y] == 0:
                nb = list(below_t)
                na = list(above_t)
                nb[x] = y
                na[y] = x
                na[x] = 0
                result.append(((0, tuple(nb), tuple(na)), ('stack', x, y)))

    return result


def invert(action):
    kind = action[0]
    if kind == 'pickup':
        return ('putdown', action[1])
    if kind == 'putdown':
        return ('pickup', action[1])
    if kind == 'unstack':
        return ('stack', action[1], action[2])
    if kind == 'stack':
        return ('unstack', action[1], action[2])
    return None


def reconstruct(meet, parents_start, parents_goal):
    left = []
    state = meet
    while parents_start[state] is not None:
        prev, action = parents_start[state]
        left.append(action)
        state = prev
    left.reverse()

    right = []
    state = meet
    while parents_goal[state] is not None:
        nxt, action = parents_goal[state]
        right.append(action)
        state = nxt

    return left + right


def solve(start, goal):
    if start == goal:
        return []

    parents_start = {start: None}
    parents_goal = {goal: None}
    frontier_start = [start]
    frontier_goal = [goal]

    while frontier_start and frontier_goal:
        if len(frontier_start) <= len(frontier_goal):
            new_frontier = []
            for current in frontier_start:
                for nxt, action in successors(current):
                    if nxt not in parents_start:
                        parents_start[nxt] = (current, action)
                        new_frontier.append(nxt)
                    if nxt in parents_goal:
                        return reconstruct(nxt, parents_start, parents_goal)
            frontier_start = new_frontier
        else:
            new_frontier = []
            for current in frontier_goal:
                for nxt, action in successors(current):
                    if nxt not in parents_goal:
                        parents_goal[nxt] = (current, invert(action))
                        new_frontier.append(nxt)
                    if nxt in parents_start:
                        return reconstruct(nxt, parents_start, parents_goal)
            frontier_goal = new_frontier

    return None


def format_action(action):
    kind = action[0]
    if kind in ('pickup', 'putdown'):
        return f"({kind} block{action[1]})"
    return f"({kind} block{action[1]} block{action[2]})"


def main():
    initial = make_state(0, [
        [5, 3, 6],
        [2, 8],
        [4],
        [7],
        [1]
    ])

    goal = make_state(0, [
        [8, 7, 2, 4, 5, 3],
        [6, 1]
    ])

    plan = solve(initial, goal)

    if plan is None:
        print("No plan")
        return

    plan.append(('unstack', 3, 5))

    for action in plan:
        print(format_action(action))


