import heapq

n = 8

start_support = (-1, 2, 3, 6, -1, -1, -1, 5)
goal_support = (-1, 6, 7, 4, 2, -1, 5, -1)


def heuristic(support, holding):
    stable = [False] * n
    changed = True
    while changed:
        changed = False
        for i in range(n):
            if not stable[i] and support[i] == goal_support[i]:
                p = support[i]
                if p == -1 or (0 <= p < n and stable[p]):
                    stable[i] = True
                    changed = True
    return n - sum(stable)


def get_successors(support, holding):
    res = []
    if holding == -1:
        on = set(support)
        for x in range(n):
            if x in on:
                continue
            if support[x] == -1:
                ns = list(support)
                ns[x] = -2
                res.append((("pickup", x), (tuple(ns), x)))
            elif support[x] >= 0:
                y = support[x]
                ns = list(support)
                ns[x] = -2
                res.append((("unstack", x, y), (tuple(ns), x)))
    else:
        x = holding
        ns = list(support)
        ns[x] = -1
        res.append((("putdown", x), (tuple(ns), -1)))

        on = set(support)
        for y in range(n):
            if y == x:
                continue
            if y in on:
                continue
            ns = list(support)
            ns[x] = y
            res.append((("stack", x, y), (tuple(ns), -1)))
    return res


def format_action(action):
    name = action[0]
    if name in ("pickup", "putdown"):
        return f"({name} block{action[1] + 1})"
    return f"({name} block{action[1] + 1} block{action[2] + 1})"


def solve():
    start = (start_support, -1)
    goal = (goal_support, -1)

    gscore = {start: 0}
    came_from = {}

    h0 = heuristic(start_support, -1)
    heap = [(h0 * 2, h0, 0, start)]

    while heap:
        _, _, g, state = heapq.heappop(heap)

        if g != gscore.get(state):
            continue

        if state == goal:
            actions = []
            cur = state
            while cur != start:
                prev, action = came_from[cur]
                actions.append(action)
                cur = prev
            actions.reverse()

            for action in actions:
                print(format_action(action))
            return

        support, holding = state
        for action, next_state in get_successors(support, holding):
            ng = g + 1
            old = gscore.get(next_state)
            if old is None or ng < old:
                gscore[next_state] = ng
