def main():
    n = 10

    initial = [0] * n
    initial[8 - 1] = 10
    start = tuple(initial)

    goal_supports = [0] * n
    goal_supports[1 - 1] = 0
    goal_supports[5 - 1] = 0
    goal_supports[7 - 1] = 5
    goal_supports[8 - 1] = 7
    goal_supports[4 - 1] = 8
    goal_supports[2 - 1] = 4
    goal_supports[6 - 1] = 0
    goal_supports[3 - 1] = 6
    goal_supports[9 - 1] = 3
    goal_supports[10 - 1] = 0
    goal_state = tuple(goal_supports)

    children = {i: [] for i in range(n + 1)}
    for top in range(1, n + 1):
        base = goal_supports[top - 1]
        children[base].append(top)

    stacks = []
    for bottom in children[0]:
        stack = []
        cur = bottom
        while True:
            stack.append(cur)
            nxt = children.get(cur, [])
            if not nxt:
                break
            cur = nxt[0]
        stacks.append(stack)

    def clear(state, block):
        for support in state:
            if support == block:
                return False
        return True

    def heuristic(state):
        locked = 0
        for stack in stacks:
            base = 0
            for block in stack:
                if state[block - 1] == base:
                    locked += 1
                    base = block
                else:
                    break
        return n - locked

    def moves(state):
        result = []
        clear_blocks = [b for b in range(1, n + 1) if clear(state, b)]

        for x in range(1, n + 1):
            if not clear(state, x):
                continue

            cur = state[x - 1]
            destinations = [0]
            for y in clear_blocks:
                if y != x:
                    destinations.append(y)

            for dest in destinations:
                if dest == cur:
                    continue
                if cur == 0 and dest == 0:
                    continue
                result.append((x, cur, dest))

        return result

    gscore = {start: 0}
    parent = {}
    counter = 0
    frontier = [(heuristic(start), 0, counter, start)]
    counter += 1

    found = False

    while frontier:
        _, g, _, state = heapq.heappop(frontier)

        if g != gscore.get(state):
            continue

        if state == goal_state:
            found = True
            break

        for x, cur, dest in moves(state):
            new_state_list = list(state)
            new_state_list[x - 1] = dest
            new_state = tuple(new_state_list)

            new_g = g + 1

            if new_g < gscore.get(new_state, 10**9):
                gscore[new_state] = new_g
                parent[new_state] = (state, x, cur, dest)
                heapq.heappush(
                    frontier,
                    (new_g + heuristic(new_state), new_g, counter, new_state),
                )
                counter += 1

    if not found:
        print("No plan")
        return

    sequence = []
    state = goal_state

    while state != start:
        prev, x, cur, dest = parent[state]
        sequence.append((x, cur, dest))
        state = prev

    sequence.reverse()

    actions = []

    for x, cur, dest in sequence:
        if cur == 0:
            actions.append(("pickup", x))
            if dest == 0:
                actions.append(("putdown", x))
            else:
                actions.append(("stack", x, dest))
        else:
            actions.append(("unstack", x, cur))
            if dest == 0:
                actions.append(("putdown", x))
            else:
                actions.append(("stack", x, dest))

    def block_name(block):
        return f"block{block}"

    output = []

    for action in actions:
        if action[0] in ("pickup", "putdown"):
            output.append(f"({action[0]} {block_name(action[1])})")
        else:
            output.append(
                f"({action[0]} {block_name(action[1])} {block_name(action[2])})"
            )

    print("\n".join(output))


if __name__ == "__main__":
    main()

def is_prime(n):
    if n < 2:
        return False
    d = 2
    while d * d <= n:
        if n % d == 0:
            return False
        d += 1
    return True

