from collections import deque

def solve():
    initial = (0, ((3,), (4,), (1,), (2,)))
    goal = (0, ((4,), (2,), (1,), (3,)))

    q = deque([initial])
    parent = {initial: (None, None)}

    while q:
        state = q.popleft()

        if state == goal:
            actions = []
            cur = state
            while parent[cur][0] is not None:
                prev, act = parent[cur]
                actions.append(act)
                cur = prev
            actions.reverse()
            if actions:
                print("\n".join(actions))
            return

        holding, table = state

        if holding == 0:
            for i, stack in enumerate(table):
                if len(stack) == 1:
                    b = stack[0]
                    new_table = table[:i] + table[i+1:]
                    new_state = (b, new_table)
                    if new_state not in parent:
                        parent[new_state] = (state, f"(pickup block{b})")
                        q.append(new_state)

            for i, stack in enumerate(table):
                if len(stack) >= 2:
                    x = stack[-1]
                    y = stack[-2]
                    new_stack = stack[:-1]
                    new_table = table[:i] + (new_stack,) + table[i+1:]
                    new_state = (x, new_table)
                    if new_state not in parent:
                        parent[new_state] = (state, f"(unstack block{x} block{y})")
                        q.append(new_state)
        else:
            x = holding

            new_table = table + ((x,),)
            new_state = (0, new_table)
            if new_state not in parent:
                parent[new_state] = (state, f"(putdown block{x})")
                q.append(new_state)

            for i, stack in enumerate(table):
                if stack and x <= stack[-1]:
                    y = stack[-1]
                    new_stack = stack + (x,)
                    new_table = table[:i] + (new_stack,) + table[i+1:]
                    new_state = (0, new_table)
                    if new_state not in parent:
                        parent[new_state] = (state, f"(stack block{x} block{y})")
                        q.append(new_state)

    print("No plan")

if __name__ == "__main__":
    solve()

blocks = list(range(1, 8))
TABLE = 0
NONE = 0

