support[7] = 0
support[1] = 0
support[2] = 0
support[4] = 2
support[6] = 0

initial = (tuple(support), NONE)

def is_clear(s, x):
    return all(s[i] != x for i in blocks)

def is_goal(state):
    s, h = state
    return h == NONE and all(s[i] == TABLE for i in blocks)

def successors(state):
    s, h = state
    result = []

    if h != NONE:
        x = h

        ns = list(s)
        ns[x] = TABLE
        result.append(((tuple(ns), NONE), f"(putdown block{x})"))

        for y in blocks:
            if y == x:
                continue
            if y == 2:
                continue
            if s[y] == -1:
                continue
            if is_clear(s, y):
                ns = list(s)
                ns[x] = y
                result.append(((tuple(ns), NONE), f"(stack block{x} block{y})"))
    else:
        for x in blocks:
            if s[x] == TABLE and is_clear(s, x):
                ns = list(s)
                ns[x] = -1
                result.append(((tuple(ns), x), f"(pickup block{x})"))

        for x in blocks:
            y = s[x]
            if y > 0 and is_clear(s, x):
                ns = list(s)
                ns[x] = -1
                result.append(((tuple(ns), x), f"(unstack block{x} block{y})"))

    return result

