import heapq
from collections import defaultdict

def main():
    stacks = [
        ["block15", "block8", "block2"],
        ["block6", "block3", "block9"],
        ["block11", "block7", "block13", "block1", "block5", "block14"],
        ["block10", "block12", "block4"]
    ]

    moves = []
    move_blocks = set()
    deps = defaultdict(set)
    support = {}

    for stack in stacks:
        for i in range(1, len(stack)):
            block = stack[i]
            below = stack[i - 1]
            moves.append((block, below))
            move_blocks.add(block)
            support[block] = below
            if i - 1 > 0:
                deps[block].add(below)

    deps["block2"].add("block1")

    graph = defaultdict(set)
    indegree = {block: 0 for block in move_blocks}

    for block in move_blocks:
        for prereq in deps[block]:
            if prereq in move_blocks:
                graph[prereq].add(block)
                indegree[block] += 1

    heap = []
    for block in move_blocks:
        if indegree[block] == 0:
            number = int(block.replace("block", ""))
            heapq.heappush(heap, (number, block))

    order = []
    while heap:
        _, block = heapq.heappop(heap)
        order.append(block)
        for nxt in graph[block]:
            indegree[nxt] -= 1
            if indegree[nxt] == 0:
                number = int(nxt.replace("block", ""))
                heapq.heappush(heap, (number, nxt))

    for block in order:
        below = support[block]
        print(f"(pickup {block})")
        print(f"(stack {block} {below})")

if __name__ == "__main__":
    main()

N = 15
on = [0] * (N + 1)

on[15] = 10
on[7] = 9
on[3] = 4
on[1] = -1
holding = 1

actions = []

def pickup(x):
    global holding
    actions.append(("pickup", x))
    holding = x
    on[x] = -1

def putdown(x):
    global holding
    actions.append(("putdown", x))
    holding = None
    on[x] = 0

def stack(x, y):
    global holding
    actions.append(("stack", x, y))
    on[x] = y
    holding = None

def unstack(x, y):
    global holding
    actions.append(("unstack", x, y))
    on[x] = -1
    holding = x

def remove_above(x):
    while True:
        child = 0
        for z in range(1, N + 1):
            if on[z] == x:
                child = z
                break
        if child == 0:
            break
        remove_above(child)
        if holding is not None:
            putdown(holding)
        unstack(child, x)
        putdown(child)

def move_to_table(x):
    if holding == x:
        putdown(x)
        return
    remove_above(x)
    if on[x] == 0:
        if holding is not None:
            putdown(holding)
        return
    else:
        if holding is not None:
            putdown(holding)
        support = on[x]
        unstack(x, support)
        putdown(x)

def stack_on(x, y):
    if on[x] == y:
        remove_above(x)
        if holding is not None:
            putdown(holding)
        return
    remove_above(y)
    remove_above(x)
    if holding is not None:
        putdown(holding)
    if on[x] == 0:
        pickup(x)
    else:
        support = on[x]
        unstack(x, support)
    stack(x, y)

